{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Tolfenamic acid absolute oral bioavailability averaged 60% in healthy volunteers across oral doses of 100-800 mg compared with IV, supporting F >= 20%."
    },
    {
      "card_ids": ["C37"],
      "claim": "Pethidine absolute oral bioavailability was 0.53 in healthy volunteers compared with IV, supporting F >= 20%."
    },
    {
      "card_ids": ["C12"],
      "claim": "Salicylic acid bioavailability after a single oral aspirin solution dose was 0.92 relative to IV, supporting F >= 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C33"],
  "decision_summary": "All transferred evidence molecules have oral bioavailability values above the 20% threshold, with absolute measurements ranging from about 41% to 97%; the only sub-20% record (C33) is an outlier for aspirin in fasting volunteers and is outweighed by direct high-F salicylate records.",
  "evidence_gaps": [
    "C08 under Molecule 1 reports morphine bioavailability, inconsistent with pethidine; discounted as a provenance conflict.",
    "C33 reports about 17% ASA availability in fasting volunteers, conflicting with high salicylate bioavailability; unresolved but outweighed by direct high-F records."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C43", "C37", "C12"],
  "revision_action": "initial",
  "supportive_card_ids": ["C43", "C37", "C12"]
}

